from flask import Flask, request, jsonify
import threading
import time
import requests
from collections import defaultdict

app_user = Flask('user_service')
app_order = Flask('order_service')
app_gateway = Flask('gateway')

# 用户服务数据
users = {}
user_id_counter = 1

@app_user.route('/users', methods=['POST'])
def create_user():
    global user_id_counter
    data = request.get_json()
    name = data.get('name')
    uid = user_id_counter
    user_id_counter += 1
    users[uid] = {'user_id': uid, 'name': name}
    return jsonify(users[uid]), 201

@app_user.route('/users/<int:uid>', methods=['GET'])
def get_user(uid):
    user = users.get(uid)
    if user:
        return jsonify(user)
    return jsonify({'error': 'User not found'}), 404

# 订单服务数据
orders = {}
order_id_counter = 1

@app_order.route('/orders', methods=['POST'])
def create_order():
    global order_id_counter
    data = request.get_json()
    user_id = data.get('user_id')
    item = data.get('item')
    try:
        resp = requests.get(f'http://localhost:5001/users/{user_id}', timeout=2)
        if resp.status_code != 200:
            return jsonify({'error': 'User not found'}), 404
    except requests.RequestException:
        return jsonify({'error': 'User service unavailable'}), 503
    oid = order_id_counter
    order_id_counter += 1
    orders[oid] = {'order_id': oid, 'user_id': user_id, 'item': item}
    return jsonify(orders[oid]), 201

# API 网关
ip_buckets = defaultdict(lambda: {'tokens': 5, 'last_time': time.time()})
RATE = 5  # 每分钟 5 次

def check_rate_limit(ip):
    bucket = ip_buckets[ip]
    now = time.time()
    elapsed = now - bucket['last_time']
    if elapsed >= 60:
        bucket['tokens'] = RATE
        bucket['last_time'] = now
    else:
        refill = int(elapsed * RATE / 60)
        bucket['tokens'] = min(RATE, bucket['tokens'] + refill)
        bucket['last_time'] = now
    if bucket['tokens'] > 0:
        bucket['tokens'] -= 1
        return True
    return False

@app_gateway.route('/<path:path>', methods=['GET', 'POST'])
def gateway(path):
    token = request.headers.get('X-Auth-Token')
    if token != 'secret':
        return jsonify({'error': 'Forbidden'}), 403
    ip = request.remote_addr or '127.0.0.1'
    if not check_rate_limit(ip):
        return jsonify({'error': 'Too Many Requests'}), 429
    if path.startswith('users'):
        target = f'http://localhost:5001/{path}'
    elif path.startswith('orders'):
        target = f'http://localhost:5002/{path}'
    else:
        return jsonify({'error': 'Not Found'}), 404
    if request.method == 'GET':
        resp = requests.get(target, timeout=5)
    else:
        resp = requests.post(target, json=request.get_json(), timeout=5)
    return (resp.text, resp.status_code)

def run_user():
    app_user.run(port=5001)

def run_order():
    app_order.run(port=5002)

def run_gateway():
    app_gateway.run(port=5000)

if __name__ == '__main__':
    t1 = threading.Thread(target=run_user, daemon=True)
    t2 = threading.Thread(target=run_order, daemon=True)
    t3 = threading.Thread(target=run_gateway, daemon=True)
    t1.start()
    t2.start()
    t3.start()
    time.sleep(2)
    print('=== 服务已启动 ===')
    print('创建用户：')
    r = requests.post('http://localhost:5000/users', json={'name': 'Alice'}, headers={'X-Auth-Token': 'secret'})
    print(r.status_code, r.json())
    print('创建订单：')
    r = requests.post('http://localhost:5000/orders', json={'user_id': 1, 'item': 'book'}, headers={'X-Auth-Token': 'secret'})
    print(r.status_code, r.json())
    print('无令牌请求：')
    r = requests.post('http://localhost:5000/orders', json={'user_id': 1, 'item': 'pen'})
    print(r.status_code, r.json())
    print('限流测试（连续 7 次请求）：')
    for i in range(7):
        r = requests.post('http://localhost:5000/users', json={'name': f'User{i}'}, headers={'X-Auth-Token': 'secret'})
        print(f'第{i+1}次:', r.status_code)
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print('关闭服务')
